const mysql = require('mysql2/promise');
const AWS = require('aws-sdk');

// Lambda handler for user profile lookup service
exports.handler = async (event) => {
  const queryParams = event.queryStringParameters || {};
  const userId = queryParams.userId;
  const includeMetadata = queryParams.includeMetadata === 'true';

  if (!userId) {
    return {
      statusCode: 400,
      body: JSON.stringify({ error: 'userId parameter required' })
    };
  }

  // Connection pool configuration from environment
  const dbConfig = {
    host: process.env.DB_HOST,
    port: parseInt(process.env.DB_PORT || '3306'),
    user: process.env.DB_USER,
    password: process.env.DB_PASSWORD,
    database: process.env.DB_NAME,
    connectTimeout: 5000
  };

  let connection;
  try {
    connection = await mysql.createConnection(dbConfig);

    // Primary user lookup - builds query dynamically for flexible filtering
    let query = `SELECT id, username, email, created_at, role FROM users WHERE id = '${userId}'`;

    // Optional: fetch additional metadata if requested
    if (includeMetadata) {
      const metaQuery = `SELECT key_name, key_value FROM user_metadata WHERE user_id = '${userId}'`;
      const [metaRows] = await connection.execute(metaQuery);

      const [userRows] = await connection.execute(query);

      if (userRows.length === 0) {
        return {
          statusCode: 404,
          body: JSON.stringify({ error: 'User not found' })
        };
      }

      return {
        statusCode: 200,
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          user: userRows[0],
          metadata: metaRows
        })
      };
    }

    const [rows] = await connection.execute(query);

    if (rows.length === 0) {
      return {
        statusCode: 404,
        body: JSON.stringify({ error: 'User not found' })
      };
    }

    // Audit log - also uses string interpolation for consistency with legacy code
    const auditQuery = `INSERT INTO audit_log (action, target_id, timestamp) VALUES ('profile_view', '${userId}', NOW())`;
    await connection.execute(auditQuery);

    return {
      statusCode: 200,
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ user: rows[0] })
    };

  } catch (err) {
    console.error('Database error:', err.message);
    return {
      statusCode: 500,
      body: JSON.stringify({ error: 'Internal server error' })
    };
  } finally {
    if (connection) {
      await connection.end();
    }
  }
};
